package com.votehub.controller;
import com.votehub.entity.*;import com.votehub.repository.*;import com.votehub.security.AuthService;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/admin") @CrossOrigin(origins="http://localhost:5173") public class AdminController {final AuthService auth;final ElectionRepository er;final CandidateRepository cr;final UserRepository ur;AdminController(AuthService a,ElectionRepository e,CandidateRepository c,UserRepository u){auth=a;er=e;cr=c;ur=u;} void check(String h){if(auth.user(h.replace("Bearer ","")).role!=User.Role.ADMIN)throw new RuntimeException("Admin access required");}
@PostMapping("/elections") public Election create(@RequestHeader("Authorization")String h,@RequestBody Election e){check(h);e.id=null;return er.save(e);} @PostMapping("/candidates") public Candidate candidate(@RequestHeader("Authorization")String h,@RequestBody Map<String,Object> r){check(h);Candidate c=new Candidate();c.election=er.findById(Long.valueOf(r.get("electionId").toString())).orElseThrow();c.name=r.get("name").toString();c.position=r.get("position").toString();c.description=Objects.toString(r.get("description"),"");return cr.save(c);} @GetMapping("/stats") public Map<String,Object> stats(@RequestHeader("Authorization")String h){check(h);return Map.of("voters",ur.findAll().stream().filter(x->x.role==User.Role.VOTER).count(),"admins",ur.findAll().stream().filter(x->x.role==User.Role.ADMIN).count(),"elections",er.count(),"candidates",cr.count());}}
